<template><view class="reviews"><view v-if="error" class="card">{{error}}<button class="ui-button" @click="load">重试</button></view><view v-if="loaded&&view.focused" class="card focus"><text class="heading">本订单的评价</text><text v-if="orderLabel" class="hint block">订单 {{orderLabel}}</text><text class="hint block">{{view.eligible.length?'以下是这笔订单中还可以评价的商品。':view.reviews.length?'这笔订单可评价的商品都已评价，可在下方查看或追评。':'这笔订单暂时没有可评价的商品：可能已全部评价、已全部退款、已过评价期限，或还没有确认收货。'}}</text><button class="ui-button plain" @click="showAll=true">查看全部待评价商品{{view.otherEligible?'（另有'+view.otherEligible+'件）':''}}</button></view><view v-else-if="loaded&&hasOrder&&showAll" class="card focus"><text class="hint block">正在显示全部待评价商品和评价记录。</text><button class="ui-button plain" @click="showAll=false">只看本订单</button></view><view v-for="i in view.eligible" :key="i.id" class="card"><text class="heading">{{i.name}} {{i.spec}}</text><view>订单 {{i.order_no}}</view><text class="hint">评价截止：{{date(i.review_until)}}</text><button class="ui-button" v-if="selected!==i.id" :disabled="busy" @click="select(i)">评价这件商品</button><template v-else><picker :disabled="busy" :range="['1星','2星','3星','4星','5星']" @change="stars=Number($event.detail.value)+1"><view class="input">{{stars?stars+'星':'请选择评分'}} ›</view></picker><textarea :disabled="busy" v-model="body" maxlength="1500" placeholder="说说您的实际使用感受" auto-height/><view><switch :disabled="busy" :checked="anonymous" @change="anonymous=$event.detail.value"/>匿名评价</view><text class="hint">评价及图片会公开展示，请勿上传个人资料。</text><view v-for="(img,n) in images" :key="img"><image :src="asset(img)" mode="aspectFill" style="width:80px;height:80px"/><text @click="removeImage(n)">移除</text></view><button class="ui-button" v-if="images.length<6" :disabled="busy" @click="pick">添加评价图片</button><button class="ui-button" :disabled="busy||!stars" @click="post(i)">发布评价</button></template></view><view v-if="loaded&&!view.focused&&!view.eligible.length" class="card">暂无可评价商品。实际确认收货后，可在规定期限内评价；已全部退款的商品无需评价。</view><view v-for="r in view.reviews" :key="'r'+r.id" class="card"><text class="heading">{{r.name}} · {{r.stars}}星</text><view>{{r.body}}</view><image v-for="img in JSON.parse(r.images_json||'[]')" :key="img" :src="asset(img)" mode="aspectFill" style="width:80px;height:80px" @click="preview(r,img)"/><text v-if="r.anonymous" class="hint">匿名发布</text><view v-if="r.followup">追评：{{r.followup}}</view><view v-if="r.reply">商家回复：{{r.reply}}</view><view v-if="!r.visible" class="hint">此评价已隐藏：{{r.moderation_note}}</view><template v-if="!r.followup&&new Date(r.followup_until).getTime()>Date.now()"><text class="hint">追评截止：{{date(r.followup_until)}}</text><textarea :disabled="busy" v-model="followups[r.id]" maxlength="1500" placeholder="补充后续使用感受，只能追评一次" auto-height/><button class="ui-button" :disabled="busy" @click="followup(r)">发布追评</button></template></view></view></template>
<script>
import {refreshOnTick} from '../services/panel-refresh'
import {reviewFocus} from '../services/review-focus'
import {request,notify,asset,uploadPublicImage,getToken} from '../services/shop.js'
import {formatDate} from '../services/display'
export default {
 mixins:[refreshOnTick()],props:{orderId:{type:[String,Number],default:''},orderNo:{type:String,default:''}},data(){return{images:[],anonymous:false,data:{eligible:[],reviews:[]},error:'',busy:false,selected:0,stars:0,body:'',followups:{},loaded:false,showAll:false,resolvedOrderNo:''}},mounted(){this.load()},
 computed:{hasOrder(){return !!(String(this.orderId||'').trim()||this.orderNo)},orderLabel(){return this.orderNo||this.resolvedOrderNo},view(){return reviewFocus(this.data,{orderId:this.orderId,orderNo:this.orderLabel},this.showAll)}},
 methods:{asset,date:formatDate,
  // Older links carry only the order id; pending items are matched by order number.
  async resolveOrderNo(){if(!this.hasOrder||this.orderLabel||!String(this.orderId||'').trim()||this.data.eligible.every(i=>i.order_id!=null))return;try{const order=(await request('/orders')).find(o=>String(o.id)===String(this.orderId));if(order?.order_no)this.resolvedOrderNo=order.order_no}catch{/* The order-id match still applies to published reviews. */}},preview(r,img){uni.previewImage({current:asset(img),urls:JSON.parse(r.images_json||'[]').map(p=>asset(p))})},
  select(i){if(this.busy)return;this.selected=i.id;this.stars=0;this.body='';this.images=[];this.anonymous=false},removeImage(index){if(!this.busy)this.images.splice(index,1)},
  pick(){return this.act(async()=>{if(!this.selected)throw Error('请先选择评价商品');const selected=this.selected,images=this.images,token=getToken();const files=await new Promise((resolve,reject)=>uni.chooseImage({count:6-images.length,success:r=>resolve(r.tempFilePaths),fail:e=>/cancel/i.test(e.errMsg||'')?resolve([]):reject(Error('选图失败，请重试'))}));for(const file of files){if(this._panelRefreshDisposed||this.selected!==selected||this.images!==images||token!==getToken())throw Error('评价对象已变化，请重新选择图片');const url=await uploadPublicImage(file);if(this._panelRefreshDisposed||this.selected!==selected||this.images!==images||token!==getToken())throw Error('评价对象已变化，请重新选择图片');images.push(url)}})},
  async load(){try{const data=await request('/reviews');this.data=data;await this.resolveOrderNo();this.error='';this.loaded=true}catch(e){this.error=e.message}},async act(fn){if(this.busy)return;this.busy=true;try{await fn();await this.load()}catch(e){notify(e)}finally{this.busy=false}},
  post(i){return this.act(async()=>{if(i.id!==this.selected)throw Error('请重新确认评价商品');const selected=this.selected,token=getToken(),payload={itemId:i.id,stars:this.stars,body:this.body,images:[...this.images],anonymous:this.anonymous};await request('/reviews','POST',payload);if(!this._panelRefreshDisposed&&this.selected===selected&&token===getToken())this.selected=0})},
  followup(r){return this.act(()=>request('/reviews/'+r.id+'/followup','POST',{body:this.followups[r.id]||''}))}
 }
}
</script>
<style scoped>
@import '../styles/component-base.css';
.reviews{padding:16px;font-size:16px}.card{padding:16px;background:var(--shop-surface, #fdfeff);border-radius:12px;margin-bottom:14px;line-height:1.8;overflow-wrap:anywhere}.heading{display:block;font-size:18px;font-weight:bold}.hint{color:var(--shop-ink, #28546c);font-size:14px}.input,textarea{padding:12px;background:var(--shop-background, #f3f8fb);margin:12px 0;width:auto}button{font-size:16px;background:var(--shop-accent, #c7e8f5);color:var(--shop-ink, #28546c);margin-top:12px}.block{display:block}.focus{background:var(--shop-background, #f3f8fb);border:1px solid var(--shop-border, #d5e6ee)}.focus .plain{background:var(--shop-surface, #fdfeff);color:var(--shop-ink, #28546c);border:1px solid var(--shop-border, #d5e6ee);font-size:15px}</style>
